svg.script:
//!export-start
let _pb_extended = false;
//!export-end

function putValue(id, value) {
  if (id === '_pb_extended') {
    _pb_extended = value;
    renderValve(value);
  }
}

function renderValve(value) {
  const indicator = document.getElementById('nex_valve_indicator');
  const status = document.getElementById('nex_valve_status');
  if (!indicator || !status) return;

  const normalized = typeof value === 'string' ? value.toLowerCase() : value;
  if (normalized === true || normalized === 1 || normalized === 'true' || normalized === '1') {
    indicator.setAttribute('fill', '#38bdf8');
    status.textContent = 'EXTENDED';
  } else if (normalized === false || normalized === 0 || normalized === 'false' || normalized === '0') {
    indicator.setAttribute('fill', '#94a3b8');
    status.textContent = 'NOT EXTENDED';
  } else {
    indicator.setAttribute('fill', '#f59e0b');
    status.textContent = 'UNKNOWN';
  }
}

renderValve(null);
